package com.shopsphere.service;
import com.shopsphere.dto.AuthDtos.*; import com.shopsphere.entity.*; import com.shopsphere.exception.ApiException; import com.shopsphere.repository.*; import com.shopsphere.security.CurrentUser; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*;
@Service public class CartService {final CartRepository carts;final CartItemRepository items;final ProductRepository products;final InventoryRepository inventory;final CurrentUser current;public CartService(CartRepository c,CartItemRepository i,ProductRepository p,InventoryRepository inv,CurrentUser cu){carts=c;items=i;products=p;inventory=inv;current=cu;}
 @Transactional public CartResponse add(org.springframework.security.core.Authentication a,CartItemRequest r){User u=current.get(a);Cart c=carts.findByUser(u).orElseGet(()->{Cart x=new Cart();x.setUser(u);return carts.save(x);});Product p=products.findById(r.productId()).filter(Product::isActive).orElseThrow(()->new ApiException("PRODUCT_NOT_FOUND","Product not found"));int stock=inventory.findByProductId(p.getId()).map(Inventory::getQuantity).orElse(0);CartItem item=items.findByCartAndProduct(c,p).orElseGet(()->{CartItem x=new CartItem();x.setCart(c);x.setProduct(p);return x;});int qty=item.getQuantity()+r.quantity();if(qty>stock)throw new ApiException("INSUFFICIENT_STOCK","Requested quantity exceeds stock");item.setQuantity(qty);items.save(item);return response(c);}
 @Transactional public void remove(org.springframework.security.core.Authentication a,UUID productId){User u=current.get(a);Cart c=carts.findByUser(u).orElseThrow();Product p=products.findById(productId).orElseThrow();items.findByCartAndProduct(c,p).ifPresent(items::delete);}
 @Transactional(readOnly=true) public CartResponse get(org.springframework.security.core.Authentication a){User u=current.get(a);Cart c=carts.findByUser(u).orElseThrow(()->new ApiException("CART_NOT_FOUND","Cart not found"));return response(c);}
 private CartResponse response(Cart c){var list=items.findAllByCart(c).stream().map(i->new CartItemResponse(i.getProduct().getId(),i.getProduct().getName(),i.getProduct().getPrice(),i.getQuantity(),i.getProduct().getPrice().multiply(BigDecimal.valueOf(i.getQuantity())))).toList();return new CartResponse(c.getId(),list,list.stream().map(CartItemResponse::lineTotal).reduce(BigDecimal.ZERO,BigDecimal::add));}
}
